/** Request for the Jwks endpoint. Takes no parameters. */
export interface JwksRequest {}

export interface DeviceCodeRequest {
  /** The ID of the application that asks for authorization. */
  clientId?: string;
  /**
   * scope is a space-delimited string that specifies the requested scope of the
   * access request.
   */
  scope?: string | null;
}

export interface DeviceCodeResponse {
  /** is the unique code for the device. When the user goes to the verification_uri in their browser-based device, this code will be bound to their session. */
  deviceCode?: string;
  /** contains the code that should be input at the verification_uri to authorize the device. */
  userCode?: string;
  /** contains the URL the user should visit to authorize the device. */
  verificationUri?: string;
  /** indicates the lifetime (in seconds) of the device_code and user_code. */
  expiresIn?: number;
  /** indicates the interval (in seconds) at which the app should poll the token URL to request a token. clients MUST use 5 as the default */
  interval?: number | null;
}

export interface DeviceAuthorizeRequest {
  /** The ID of the application that asks for authorization. */
  clientId?: string;
  /** scope is a space-delimited string that specifies the requested scope of the access request. */
  scope?: string | null;
  /**
   * OIDC nonce, bound to the device authorization and echoed back in the id_token at /token.
   * @maxLength 512
   */
  nonce?: string | null;
}

export interface DeviceAuthorizeResponse {
  /** the unique code for the device, used to poll the token endpoint. */
  deviceCode?: string;
  /** the code the user enters at the verification_uri to authorize the device. */
  userCode?: string;
  /** the URL the user should visit to authorize the device. */
  verificationUri?: string;
  /** the verification_uri with the user_code embedded as a query param, ready to encode into a QR code. */
  verificationUriComplete?: string;
  /** lifetime (in seconds) of the device_code and user_code. */
  expiresIn?: number;
  /** interval (in seconds) at which the client should poll the token endpoint. clients MUST use 5 as the default. */
  interval?: number | null;
}

export interface DeviceVerifyRequest {
  /** User code representing a currently authorizing device. */
  userCode?: string;
}

export interface DeviceVerifyResponse {}

export interface DeviceVerifyV2Request {
  /**
   * User code representing a currently authorizing device.
   * @minLength 8
   * @maxLength 8
   */
  userCode?: string;
}

export interface DeviceVerifyV2Response {}

export interface DeviceAuthorizationInfoRequest {
  /**
   * User code representing a currently authorizing device.
   * @minLength 8
   * @maxLength 8
   */
  userCode?: string;
}

export interface DeviceAuthorizationInfoResponse {
  /** The ID of the application the device is authorizing into. */
  clientId?: string;
  /** Canonical browser name of the initiating browser (e.g. "chrome"). */
  browser?: string | null;
  /** Canonical OS of the initiating browser (e.g. "windows"). */
  os?: string | null;
  /** Canonical device class of the initiating browser (e.g. "desktop"). */
  deviceClass?: string | null;
  /** IP address of the initiating browser. */
  browserIp?: string | null;
  /** Coarse geo-location (country, optional region) derived from the browser IP, e.g. "IL" or "US-NY". */
  geo?: string | null;
}

